//! R9 deterministic opportunity decision parity gate; review-only.
use serde_json::json;
fn vwap(levels:&[(f64,f64)],q:f64)->Result<f64,&'static str>{let(mut left,mut total)=(q,0.);for&(p,a)in levels{let t=left.min(a);total+=t*p;left-=t;if left<=q*1e-9{return Ok(total/q)}}Err("DEPTH_DENY")}
fn eval(asks:&[(f64,f64)],bids:&[(f64,f64)],q:f64,cost:f64,threshold:f64)->serde_json::Value{let req=q*asks[0].0.max(bids[0].0);let(s,f)=match(vwap(asks,q),vwap(bids,q)){(Ok(s),Ok(f))=>(s,f),_=>return json!({"reason":"DEPTH_DENY","executable":false,"requested_size_usdt":(req*1e6).round()/1e6})};let sn=s*q;let fnn=f*q;let gross=(f/s-1.)*10000.;let net=gross-cost;let reason=if sn.max(fnn)>500.0000001{"ABOVE_RESEARCH_CEILING"}else if net>=threshold{"EXECUTABLE_OPPORTUNITY"}else{"EDGE_TOO_LOW"};json!({"reason":reason,"executable":reason=="EXECUTABLE_OPPORTUNITY","spot_vwap":(s*1e10).round()/1e10,"futures_vwap":(f*1e10).round()/1e10,"gross_executable_bps":(gross*1e4).round()/1e4,"estimated_net_bps":(net*1e4).round()/1e4})}
fn main(){let cases=[("exec",vec![(100.,2.)],vec![(101.,2.)],1.,20.,42.,"EXECUTABLE_OPPORTUNITY"),("edge",vec![(100.,2.)],vec![(100.5,2.)],1.,20.,42.,"EDGE_TOO_LOW"),("depth",vec![(100.,0.2)],vec![(101.,2.)],1.,20.,42.,"DEPTH_DENY"),("ceiling",vec![(100.,10.)],vec![(101.,10.)],6.,20.,42.,"ABOVE_RESEARCH_CEILING"),("multi",vec![(100.,0.5),(100.2,0.5)],vec![(101.,0.5),(100.8,0.5)],1.,20.,42.,"EXECUTABLE_OPPORTUNITY")];let mut fail=vec![];for(n,a,b,q,c,t,w)in cases{let r=eval(&a,&b,q,c,t);if r["reason"]!=w{fail.push(json!({"case":n,"got":r["reason"],"want":w}))}}println!("{}",json!({"r9_sample_parity_gate":fail.is_empty(),"cases":5,"failures":fail,"trading":false}));}